def _local_decision(parsed, ingress, gateway, accounts, aliases, domains):
    subject = ingress.get('subject')
    account = accounts.get(subject) if isinstance(subject, str) else None
    if not isinstance(account, dict):
        raise Reject(UNAUTHENTICATED)
    primary = account.get('primary')
    allowed = set()
    extra = account.get('allow')
    if isinstance(extra, list):
        for item in extra:
            if isinstance(item, str):
                allowed.add(item)
    allowed.add(primary)
    hosted = set()
    local = gateway.get('local_domains')
    if isinstance(local, list):
        for domain in local:
            if isinstance(domain, str):
                hosted.add(domain.lower())

    def authorized(canonical):
        if canonical is None or canonical not in allowed:
            return False
        domain = domains.get(canonical)
        return domain is not None and domain in hosted

    from_anonymous = parsed['from_anonymous']
    from_canonical = None
    if not from_anonymous:
        from_canonical = aliases.get(parsed['from_uri'])
        if not authorized(from_canonical):
            raise Reject(IDENTITY)
    ppi = parsed['ppi']
    ppi_canonical = None
    if ppi is not None:
        ppi_canonical = aliases.get(ppi)
        if not authorized(ppi_canonical):
            raise Reject(IDENTITY)

    if ppi is not None:
        selected = ppi_canonical
    elif not from_anonymous:
        selected = from_canonical
    else:
        selected = primary
        if not authorized(selected):
            raise Reject(IDENTITY)
    return selected, from_anonymous


def _peer_decision(parsed, ingress, gateway, aliases, domains):
    name = ingress.get('name')
    peers = gateway.get('peers')
    authority = None
    if isinstance(peers, dict) and isinstance(name, str):
        raw = peers.get(name)
        if isinstance(raw, list):
            authority = set()
            for domain in raw:
                if isinstance(domain, str):
                    authority.add(domain.lower())
    if authority is None:
        raise Reject(UNAUTHENTICATED)
    pai = parsed['pai']
    if not pai:
        raise Reject(UNAUTHENTICATED)
    resolved = []
    for uri in pai:
        canonical = aliases.get(uri)
        if canonical is None:
            raise Reject(IDENTITY)
        resolved.append(canonical)
    selected = resolved[0]
    for canonical in resolved[1:]:
        if canonical != selected:
            raise Reject(IDENTITY)
    domain = domains.get(selected)
    if domain is None or domain not in authority:
        raise Reject(IDENTITY)
    if not parsed['from_anonymous']:
        if aliases.get(parsed['from_uri']) != selected:
            raise Reject(IDENTITY)
    for uri in (parsed['ppi'], parsed['rpid']):
        if uri is not None and aliases.get(uri) != selected:
            raise Reject(IDENTITY)
    return selected, parsed['from_anonymous']


def _build_wire(parsed, selected, private, trusted_out):
    from_uri = ANONYMOUS if private else selected
    lines = [parsed['method'] + ' ' + parsed['requri'] + ' SIP/2.0']
    line = 'From: <' + from_uri + '>'
    if parsed['from_tag']:
        line += ';tag=' + parsed['from_tag']
    lines.append(line)
    line = 'To: <' + parsed['to_uri'] + '>'
    if parsed['to_tag']:
        line += ';tag=' + parsed['to_tag']
    lines.append(line)
    lines.append('Call-ID: ' + parsed['call_id'])
    lines.append('CSeq: %d %s' % (parsed['cseq'], parsed['method']))
    lines.append('Privacy: ' + ('id' if private else 'none'))
    if (not private) or trusted_out:
        lines.append('P-Asserted-Identity: <' + selected + '>')
    if parsed['content_type'] is not None:
        lines.append('Content-Type: ' + parsed['content_type'])
    lines.append('Content-Length: %d' % len(parsed['body']))
    return '\r\n'.join(lines) + '\r\n\r\n' + parsed['body']


def process_job(job, index, jobs, wires, aliases, domains, accounts, gateways):
    text = None
    if 'raw' in job:
        raw = job['raw']
        if not isinstance(raw, str):
            raise Reject(UPSTREAM)
        text = raw
    elif 'source' in job:
        source = job['source']
        if type(source) is not int:
            raise Reject(UPSTREAM)
        if source < 0 or source >= index:
            raise Reject(UPSTREAM)
        text = wires[source]
        if text is None:
            raise Reject(UPSTREAM)
    else:
        raise Reject(UPSTREAM)

    parsed = _parse_request(text)

    ingress = job.get('ingress')
    if not isinstance(ingress, dict):
        raise Reject(UNAUTHENTICATED)
    kind = ingress.get('kind')
    if kind == 'local':
        gateway = gateways.get(job.get('gateway'))
        if not isinstance(gateway, dict):
            raise Reject(UNAUTHENTICATED)
        selected, from_anonymous = _local_decision(
            parsed, ingress, gateway, accounts, aliases, domains)
        basis = 'local'
    elif kind == 'peer':
        gateway = gateways.get(job.get('gateway'))
        if not isinstance(gateway, dict):
            raise Reject(UNAUTHENTICATED)
        selected, from_anonymous = _peer_decision(
            parsed, ingress, gateway, aliases, domains)
        basis = 'peer'
    else:
        raise Reject(UNAUTHENTICATED)

    private = from_anonymous or parsed['privacy'] == 'id'
    trusted_out = bool(job.get('trusted_out'))
    wire = _build_wire(parsed, selected, private, trusted_out)
    return {
        'status': 'accept',
        'identity': selected,
        'basis': basis,
        'private': private,
        'wire': wire,
    }


